def find_shortest_sub_array(nums):
    n = len(nums)
    from collections import Counter
    degree = max(Counter(nums).values())
    best = n
    for start in range(n):
        for end in range(start, n):
            window = nums[start:end + 1]                                   # slice out every candidate window directly
            counts = Counter(window)
            if max(counts.values()) == degree and len(window) < best:
                best = len(window)
                break                                                        # any longer window from this same start is never shorter
    return best


if __name__ == "__main__":
    print(find_shortest_sub_array([1, 2, 2, 3, 1]))

