import java.util.*;

public class Main {
    int findShortestSubArray(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> fullCount = new HashMap<>();
        for (int x : nums) fullCount.merge(x, 1, Integer::sum);
        int degree = Collections.max(fullCount.values());
        int best = n;
        for (int start = 0; start < n; start++) {
            for (int end = start; end < n; end++) {
                Map<Integer, Integer> counts = new HashMap<>();
                int localMax = 0;
                for (int i = start; i <= end; i++) {
                    counts.merge(nums[i], 1, Integer::sum);                        // build up this candidate window's counts directly
                    localMax = Math.max(localMax, counts.get(nums[i]));
                }
                if (localMax == degree) {
                    best = Math.min(best, end - start + 1);
                    break;                                                          // any longer window from this same start is never shorter
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findShortestSubArray(new int[]{1, 2, 2, 3, 1}));
    }
}

