        int localMax = 0;
        for (int end = start; end < n; end++) {
            counts[nums[end]]++;                                                // build up this candidate window's counts directly
            localMax = max(localMax, counts[nums[end]]);
            if (localMax == degree) {
                best = min(best, end - start + 1);
                break;                                                            // any longer window from this same start is never shorter
            }
        }
    }
    return best;
}

