    last = {}
    count = {}
    degree = 0
    for i, x in enumerate(nums):
        if x not in first:
            first[x] = i                                                   # remember only the FIRST time this value appears
        last[x] = i                                                         # keep overwriting with the LATEST time this value appears
        count[x] = count.get(x, 0) + 1
        degree = max(degree, count[x])
    best = len(nums)
    for x in count:
        if count[x] == degree:
            best = min(best, last[x] - first[x] + 1)                       # the tightest span containing every occurrence of this value
    return best


