public class Main {
    int findShortestSubArray(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        Map<Integer, Integer> last = new HashMap<>();
        Map<Integer, Integer> count = new HashMap<>();
        int degree = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            first.putIfAbsent(x, i);                                              // remember only the FIRST time this value appears
            last.put(x, i);                                                       // keep overwriting with the LATEST time this value appears
            count.merge(x, 1, Integer::sum);
            degree = Math.max(degree, count.get(x));
        }
        int best = nums.length;
        for (int x : count.keySet()) {
            if (count.get(x) == degree) {
                best = Math.min(best, last.get(x) - first.get(x) + 1);              // the tightest span containing every occurrence of this value
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findShortestSubArray(new int[]{1, 2, 2, 3, 1}));
    }
}

