#include <bits/stdc++.h>
using namespace std;

int findShortestSubArray(vector<int>& nums) {
    unordered_map<int,int> first, last, count;
    int degree = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        int x = nums[i];
        if (!first.count(x)) first[x] = i;                                       // remember only the FIRST time this value appears
        last[x] = i;                                                              // keep overwriting with the LATEST time this value appears
        count[x]++;
        degree = max(degree, count[x]);
    }
    int best = (int)nums.size();
    for (auto& [x, c] : count) {
        if (c == degree) {
            best = min(best, last[x] - first[x] + 1);                              // the tightest span containing every occurrence of this value
        }
    }
    return best;
}

int main() {
    vector<int> nums = {1, 2, 2, 3, 1};
    cout << findShortestSubArray(nums) << endl;
    return 0;
}
